function shortestMirror(s: string): string {
  const isPal = (end: number) => {
    for (let i = 0, j = end - 1; i < j; i++, j--) if (s[i] !== s[j]) return false;
    return true;
  };
  let k = s.length;
  while (k > 0 && !isPal(k)) k--;
  return s.slice(k).split("").reverse().join("") + s;
}

